import { supabase } from '../../config/supabase.js';
import { sendError, sendPage } from '../../utils/respond.js';

/**
 * Canonical 8-4-4-4-12 hex UUID.
 *
 * This is a SECURITY control, not tidiness. `getChatHistory` builds a PostgREST
 * `.or()` filter by string interpolation, and unlike `.eq()` — where supabase-js
 * encodes the value — an `.or()` argument is a filter EXPRESSION that is parsed
 * server-side. A value carrying `,` or `)` closes the expression early and
 * appends conditions of the attacker's choosing, so the only safe move is to
 * refuse anything that is not literally a uuid before it reaches the string.
 *
 * Anchored, and no character class that can match a comma, parenthesis or dot.
 */
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const isUuid = (value) => typeof value === 'string' && UUID_RE.test(value);

