const PAGE_LIMIT_DEFAULT = 20;
const PAGE_LIMIT_MAX = 50;

/** Cap first, then floor — the rule from `user.controller.js -> searchUsers`. */
function parsePageLimit(raw) {
    const requested = Number.parseInt(raw, 10);
    return Number.isNaN(requested)
        ? PAGE_LIMIT_DEFAULT
        : Math.min(Math.max(requested, 1), PAGE_LIMIT_MAX);
}

/** Absent unless a non-empty string. `?cursor=` and a repeated cursor mean page one. */
function readCursorParam(raw) {
    return typeof raw === 'string' && raw.length > 0 ? raw : null;
}

/** Parseable as an instant. Guards the query against a 22007 cast error -> 500. */
function isTimestamp(value) {
    return typeof value === 'string' && !Number.isNaN(Date.parse(value));
}

/**
 * Compound cursor, `created_at|id`, base64url. Messages ARE bulk-inserted by
 * the seed scripts, so several sharing a timestamp to the microsecond is
 * normal, and a timestamp-only cursor on a tie either drops the rest of the
 * tied group or serves it forever. `id` is the primary key, so the pair is
 * unique. base64url because the payload's `+00:00` offset and `=` padding both
 * need escaping in a query string.
 */
function encodeMessageCursor(row) {
    return Buffer.from(`${row.created_at}|${row.id}`, 'utf8').toString('base64url');
}

/**
 * Returns `{ created_at, id }`, or `null` for anything this endpoint did not
 * issue. `Buffer.from(..., 'base64url')` does not throw on junk — it drops what
 * it cannot read — so the decode is not the check; validating both halves is.
 * A `null` here MUST become a 400, never an interpolation into the `.or()`
 * expression: the id half lands in a filter PostgREST parses server-side, which
 * is the same hazard the UUID_RE above exists for.
 */
function decodeMessageCursor(raw) {
    let decoded;
    try {
        decoded = Buffer.from(raw, 'base64url').toString('utf8');
    } catch {
        return null;
    }

    const parts = decoded.split('|');
    if (parts.length !== 2) return null;

    const [created_at, id] = parts;
    if (!isTimestamp(created_at)) return null;
    if (!isUuid(id)) return null;

    return { created_at, id };
}

// 1. Get the Inbox Summary (Calls our new RPC)
export const getInbox = async (req, res) => {
    try {
        // 🔒 IDENTITY (Phase 4 Block V-A). This route had no auth at all and the
        // inbox it returned was whichever uuid was in the URL — every
        // conversation, contact name and last message of any student on any
        // campus, to anyone who could guess or scrape an id.
        //
        // The path param is KEPT, not removed: both clients build the URL and
        // the path must not change. It is compared to the token instead of
        // trusted, which is the difference between a parameter and a claim.
        //
        // Compared rather than ignored (the `updateProfile` treatment) because
        // this handler reads rather than writes: ignoring a mismatched id would
        // silently answer with the caller's OWN inbox, and a client asking for
        // someone else's is confused, not merely out of date. It should hear so.
        const { userId } = req.params;
        if (userId !== req.user.id) {
            return sendError(res, 403, 'FORBIDDEN', {
                message: 'You can only read your own inbox.',
            });
        }

        // 📄 PAGINATION (Phase 4 Block N-C). Both params optional; both clients
        // send neither today and keep working, they just receive 20 rows.
        //
        // The RPC gained `p_limit` and `p_cursor` in Vishwajeet's Block V-C
        // (migration 20260915070505_inbox_pagination). It clamps the limit
        // itself — 100000 -> 50, 0/-1 -> 1, null -> 20 — so this parse is the
        // belt to the RPC's braces, not the only guard.
        //
        // The cursor is a bare `last_message_time`, the column the RPC orders
        // by, DESCENDING. Not the compound cursor `getChatHistory` below uses:
        // the RPC exposes no tiebreaker to seek on, so a plain timestamp is the
        // only cursor it can accept. V-C documents the resulting edge case —
        // two conversations sharing a `last_message_time` to the microsecond
        // across a page boundary can skip one. Fixing it needs a change to the
        // RPC's return columns, which is a migration and therefore Vishwajeet's.
        const limit = parsePageLimit(req.query.limit);
        const cursor = readCursorParam(req.query.cursor);

        // A non-timestamp would reach `p_cursor timestamptz` and make Postgres
        // raise 22007, which the catch below would report as a 500 on what is
        // plainly a bad request.
        if (cursor !== null && !isTimestamp(cursor)) {
            return sendError(res, 400, 'INVALID_FORMAT', {
                message: 'cursor must be the next_cursor value from a previous response.',
            });
        }

        const { data, error } = await supabase.rpc('get_user_inbox', {
            p_user_id: req.user.id,
            p_limit: limit,
            p_cursor: cursor
        });

        if (error) throw error;

        // 📄 `{ items, next_cursor }` via the frozen sendPage(). This replaces
        // `{ inbox }`: the envelope key changed, the nine RPC columns did not.
        return sendPage(res, data || [], 'last_message_time', limit);
    } catch (error) {
        console.error('Get Inbox Error:', error);
        res.status(500).json({ error: 'Failed to fetch inbox.' });
    }
};

// 2. Get Chat History (Between two specific users for a specific product)
export const getChatHistory = async (req, res) => {
    try {
        const { userId, contactId, productId } = req.query;

        // 🔒 1. FILTER INJECTION (CURRENT_STATE item 3).
        //
        // All three land in the query below and `userId`/`contactId` are
        // interpolated into an `.or()` filter EXPRESSION, which PostgREST parses
        // rather than treats as a value. Validate before they reach the string:
        // once concatenated it is too late, and there is nothing to escape with.
        //
        // productId is checked too. It only reaches `.eq()`, which is safe from
        // injection, but a non-uuid there makes Postgres raise 22P02 and the
        // old code turned that into a 500 on what is really a bad request.
        if (!isUuid(userId) || !isUuid(contactId) || !isUuid(productId)) {
            return sendError(res, 400, 'INVALID_FORMAT', {
                message: 'userId, contactId and productId must all be valid UUIDs.',
            });
        }

        // 🔒 2. PARTICIPATION.
        //
        // Validation alone still let anyone read any thread by naming two other
        // students. The caller must be one of the two parties.
        //
        // Either side is accepted on purpose — the thread is symmetric, so a
        // client that passes the pair in the other order is still asking for
        // its OWN conversation. Pinning userId to req.user.id would reject that
        // legitimate call for no security gain.
        if (req.user.id !== userId && req.user.id !== contactId) {
            return sendError(res, 403, 'FORBIDDEN', {
                message: 'You can only read conversations you are part of.',
            });
        }

        // 📄 PAGINATION (Phase 4 Block N-C) — and the direction here is the
        // opposite of the render order, which is the whole difficulty.
        //
        // A chat renders OLDEST FIRST (top to bottom). But when the thread
        // opens you are looking at the NEWEST messages, and scrolling UP loads
        // OLDER ones. So the page is taken from the newest end and walks
        // backwards in time, while the array handed to the client must still
        // read oldest-first or every rendering loop on both surfaces breaks.
        //
        // Query DESCENDING, take `limit`, then REVERSE just before sending.
        const limit = parsePageLimit(req.query.limit);
        const rawCursor = readCursorParam(req.query.cursor);

        // Compound cursor: the seed scripts bulk-insert messages, so ties on
        // `created_at` are normal here. Anything that is not a cursor this
        // endpoint issued stops at a 400 — above all it never reaches the
        // `.or()` string below, which PostgREST parses as an expression.
        const cursor = rawCursor === null ? null : decodeMessageCursor(rawCursor);
        if (rawCursor !== null && cursor === null) {
            return sendError(res, 400, 'INVALID_FORMAT', {
                message: 'cursor must be the next_cursor value from a previous response.',
            });
        }

        let query = supabase
            .from('messages')
            .select('*')
            .eq('product_id', productId)
            .or(`and(sender_id.eq.${userId},receiver_id.eq.${contactId}),and(sender_id.eq.${contactId},receiver_id.eq.${userId})`)
            // Newest first HERE ONLY, so that `limit` takes the newest page and
            // the cursor can walk backwards. Reversed below before sending.
            .order('created_at', { ascending: false })
            .order('id', { ascending: false })
            .limit(limit);

        // "Older than the cursor row, or the same instant with a lower id."
        // The second leg is what makes a tie total. This is a SECOND `.or()` on
        // the same query — PostgREST ANDs repeated top-level filters, so the
        // participant pair above is still enforced and cannot be widened by it.
        // Verified against the local database, not assumed.
        if (cursor !== null) {
            query = query.or(
                `created_at.lt."${cursor.created_at}",` +
                `and(created_at.eq."${cursor.created_at}",id.lt.${cursor.id})`
            );
        }

        const { data, error } = await query;

        if (error) throw error;

        const page = data || [];

        // 📄 next_cursor BEFORE the reverse, and NOT via sendPage().
        //
        // sendPage() takes the cursor from the LAST element, which is correct
        // for every descending list in this API. This is the one endpoint that
        // hands back an ASCENDING array, so after the reverse the last element
        // is the NEWEST message on the page — paging on it would walk forward
        // into messages the client already has and never load the older ones.
        //
        // `page` is still descending at this point, so `page[page.length - 1]`
        // is the OLDEST message, which is exactly what "scroll up for more"
        // continues from. After the reverse the same row is `items[0]`.
        //
        // respond.js is frozen and is right as it stands — this is the caller
        // adapting to it, not a second envelope. The shape returned below is
        // byte-identical to sendPage's: `{ items, next_cursor }`, and the
        // end-of-list rule is the same (a full page means there may be more).
        const oldestOnPage = page.length === limit ? page[page.length - 1] : null;
        const next_cursor = oldestOnPage ? encodeMessageCursor(oldestOnPage) : null;

        // Oldest first for the chat UI — unchanged from what clients render today.
        const items = page.slice().reverse();

        return res.status(200).json({ items, next_cursor });
    } catch (error) {
        console.error('Get Chat History Error:', error);
        return sendError(res, 500, 'INTERNAL_ERROR', {
            message: 'Failed to fetch messages.',
        });
    }
};

// 3. Send a Message
export const sendMessage = async (req, res) => {
    try {
        // 🔒 IDENTITY (Phase 4 Block V-A). `sender_id` used to come from the
        // body, so an unauthenticated caller could post a message that arrived
        // in a real student's thread under a real student's name — the worst of
        // the nine holes in this block, because the forgery is persistent and
        // indistinguishable from a genuine message once it is in the table.
        //
        // The sender is the token holder. A `sender_id` in the body is ignored
        // in silence; both clients still send one today.
        const sender_id = req.user.id;
        const { receiver_id, product_id, content } = req.body;

        // 🔒 CAMPUS (Phase 4 Block V-A). The lookup below used to read the
        // CLAIMED sender's row and stamp that campus on the message, so it
        // validated nothing: the id it checked was the same id the caller had
        // just made up. It now reads the AUTHENTICATED sender.
        //
        // The receiver is checked too, which is new. Reading the sender's campus
        // only decides what to stamp on the row; it never asked whether the two
        // people share one. Yahora's rule is that a conversation lives inside a
        // campus, and without this check the cross-campus browse that
        // `getProducts` allows turned into a cross-campus DM.
        //
        // Both reads are independent, so they cost one round trip rather than
        // two. maybeSingle, not single: a missing row is a 404 here, not a 500.
        const [senderRes, receiverRes] = await Promise.all([
            supabase.from('users').select('university_id').eq('id', sender_id).maybeSingle(),
            supabase.from('users').select('university_id').eq('id', receiver_id).maybeSingle(),
        ]);

        if (senderRes.error || receiverRes.error) {
            console.error('Send Message Error (campus lookup):', senderRes.error || receiverRes.error);
            return sendError(res, 500, 'INTERNAL_ERROR', {
                message: 'Failed to send message.',
            });
        }

        const user = senderRes.data;

        if (!user) {
            return sendError(res, 404, 'NOT_FOUND', {
                message: 'No profile exists for this account.',
            });
        }

        if (!receiverRes.data) {
            return sendError(res, 404, 'NOT_FOUND', {
                message: 'That student no longer exists.',
            });
        }

        // A NULL on either side is a mismatch, not a pass — same rule as
        // `blockCrossCampusInteraction` in the products module. `handle_new_user`
        // (migration 005) writes university_id NULL when the email domain is
        // unknown, and "I could not establish you are on the same campus" must
        // fail closed. No real student is affected: every account created
        // through requestOtp has a validated domain and therefore a campus.
        if (!user.university_id || !receiverRes.data.university_id
            || user.university_id !== receiverRes.data.university_id) {
            return sendError(res, 403, 'FORBIDDEN', {
                message: 'You can only message students on your own campus.',
            });
        }

        const { data: message, error } = await supabase
            .from('messages')
            .insert([{
                sender_id,
                receiver_id,
                product_id,
                university_id: user.university_id,
                content,
                is_read: false
            }])
            .select()
            .single();

        if (error) throw error;

        // Immediately return success to the sender
        res.status(201).json({ message });

        /* HE DEMO AUTO-RESPONDER BOT */
        try {
            // Check if this interaction is happening in the Demo Campus
            const { data: uni } = await supabase
                .from('universities')
                .select('domain')
                .eq('id', user.university_id)
                .single();

            if (uni?.domain === 'demo.yahora.com') {
                // Fetch the receiver's name to personalize the bot response
                const { data: receiver } = await supabase
                    .from('users')
                    .select('full_name')
                    .eq('id', receiver_id)
                    .single();

                if (receiver) {
                    const firstName = receiver?.full_name?.split(' ')[0] || 'Student';

                    // A list of smart responses to make it feel natural
                    const botResponses = [
  `Hey! ${firstName} here — well, sort of. I'm the auto-responder standing in while the real ${firstName} is probably buried under assignments. In the actual app, I'd be a real student ready to close this deal! 👋`,
  `${firstName} (bot edition) speaking 🤖. Real talk — the actual ${firstName} has no idea you just messaged them. But I do, and I think you have great taste for checking out this listing.`,
  `Okay okay, I'll come clean. I'm not really ${firstName}. I'm a bot with ${firstName}'s name badge and absolutely none of their charm. But hey, the messaging feature works flawlessly, doesn't it? ⚡`,
  `*${firstName} is typing...* — Nah, just kidding. It's the bot again. But in ${firstName}'s defence, they'd probably have replied with "still available, bro. come to hostel B." 🏠`,
  `${firstName} would want me to tell you: yes, the item is in great condition, the price is negotiable, and they're free after 5 PM near the canteen. (This is entirely made up. But very realistic, right?) 😄`,
  `Plot twist — ${firstName} didn't list this at 2 AM during a spontaneous hostel room cleanout. Or did they? 🌙 Either way, on real Yahora this reply would've come from the actual ${firstName} in seconds.`,
  `Hi! Bot-${firstName} here with a fun fact: this message just traveled through Yahora Realtime, hit the server, triggered an auto-responder, and landed in your chat — all in under 3 seconds. ${firstName} could never. 🚀`,
  `${firstName}'s out-of-office bot response: "Thanks for your message! I'm currently in a lecture pretending to take notes. Please leave a bid and I'll get back to you after the professor stops looking." 📝`,
  `Genuinely cannot stress this enough — the real ${firstName} is a verified student on a real campus. No random strangers. No scammers. Just broke college kids selling stuff they no longer need. That's the Yahora difference. 🎓`,
  `${firstName}'s bot here, filing an official complaint: I've been answering messages all day and nobody has offered me a coffee. The canteen is literally 200 metres away. Just saying. ☕`,
  `Alright, that's a wrap on the demo! The real ${firstName} is out there somewhere on campus, waiting to make their first Yahora sale. Go sign up with your university email and make it happen. Keep the story going. 🛍️✨`,
];
                    const randomReply = botResponses[Math.floor(Math.random() * botResponses.length)];

                    // Wait 3 seconds, then programmatically insert the bot's reply
                    setTimeout(async () => {
                        await supabase.from('messages').insert([{
                            sender_id: receiver_id,   // Bot acts as the sender
                            receiver_id: sender_id,   // VC is the receiver
                            product_id,
                            university_id: user.university_id,
                            content: randomReply,
                            is_read: false
                        }]);
                    }, 3000);
                }
            }
        } catch (botErr) {
            console.error('Bot Auto-Responder Error:', botErr);
        }
        /* ======================================================== */

    } catch (error) {
        console.error('Send Message Error:', error);
        res.status(500).json({ error: 'Failed to send message.' });
    }
};

// 4. Mark Messages as Read
export const markAsRead = async (req, res) => {
    try {
        // 🔒 IDENTITY (Phase 4 Block V-A). `userId` is the RECEIVER — the person
        // doing the reading — and it came from the body, so any caller could
        // clear the unread badge on any student's threads. It is the token
        // holder now; a `userId` in the body is ignored in silence.
        //
        // `contactId` and `productId` still come from the body and still should:
        // they name WHICH thread to mark, not who is marking it, and the update
        // is anchored to `receiver_id = req.user.id` either way.
        const userId = req.user.id;
        const { contactId, productId } = req.body;
        const { error } = await supabase
            .from('messages')
            .update({ is_read: true, is_delivered: true }) // <-- added is_delivered: true
            .eq('receiver_id', userId)
            .eq('sender_id', contactId)
            .eq('product_id', productId)
            .eq('is_read', false);

        if (error) throw error;
        res.status(200).json({ success: true });
    } catch (error) {
        console.error('Mark as Read Error:', error);
        res.status(500).json({ error: 'Failed to update read status.' });
    }
};

export const markAsDelivered = async (req, res) => {
    try {
        // 🔒 IDENTITY (Phase 4 Block V-A). Was `req.body.userId`, and this one is
        // global rather than per-thread — a single call marked every undelivered
        // message addressed to any named student as delivered, destroying the
        // "not yet delivered" state across all of their conversations at once.
        // The receiver is the token holder; a `userId` in the body is ignored.
        const userId = req.user.id;
        // Marks all messages sent TO this user as delivered (because they just opened the app)
        const { error } = await supabase
            .from('messages')
            .update({ is_delivered: true })
            .eq('receiver_id', userId)
            .eq('is_delivered', false);

        if (error) throw error;
        res.status(200).json({ success: true });
    } catch (error) {
        console.error('Mark as Delivered Error:', error);
        res.status(500).json({ error: 'Failed to update delivery status.' });
    }
};